//! Item 5, first half: `with`, private class members, static blocks, class fields,
//! `new.target`, computed / numeric member names, labelled blocks.

pub const CASES: &[(&str, &str)] = &[
    // --- with: lookup, shadowing, assignment
    (r#"with ({ a: 1 }) { a }"#, "1"),
    (r#"var o = { x: 1 }; var x = 'outer'; with (o) { x = 2; var y = x + 1 } [o.x, x, y].join()"#, "2,outer,3"),
    (r#"function f(o) { var v = 'local'; with (o) { return v + '|' + w } } f({ w: 'from-with' }) + ' ' + f({ w: 1, v: 2 })"#, "local|from-with 2|1"),
    (r#"var a = 'global'; function f() { var a = 'local'; with ({ a: 'with' }) { var inner = a; with ({}) { inner += '|' + a } } return inner + '|' + a } f() + '|' + a"#, "with|with|local|global"),
    (r#"with ({ a: 1 }) { with ({ b: 2, a: 10 }) { out = a + b } }"#, "12"),
    (r#"var o = { n: 1 }; with (o) { n++; n += 5; var copy = n } o.n + '|' + copy + '|' + typeof n"#, "7|7|undefined"),
    (r#"var o = {}; with (o) { fresh = 1 } typeof o.fresh + '|' + fresh"#, "undefined|1"),
    (r#"var o = { v: 1 }; with (o) { var v = 2; var w = 3 } o.v + '|' + v + '|' + w + '|' + ('w' in o)"#, "2|undefined|3|false"),
    (r#"function f() { with ({ m() { return this.tag }, tag: 'T' }) { return m() } } f()"#, "T"),
    (r#"var o = { a: 1 }; with (o) { var fn = function () { return a } } o.a = 5; fn()"#, "5"),
    (r#"with ([1, 2, 3]) { length + '|' + join('-') + '|' + typeof keys }"#, "3|1-2-3|undefined"),
    (r#"var o = { a: 1, [Symbol.unscopables]: { a: true } }; var a = 'g'; with (o) { a }"#, "g"),
    (r#"with ({ z: 1 }) { typeof z + '|' + typeof nope }"#, "number|undefined"),
    (r#"var o = { a: 1 }; with (o) { delete a } 'a' in o"#, "false"),
    (r#"var r = []; for (var i = 0; i < 3; i++) { with ({ i2: i * 2 }) { if (i == 1) continue; r.push(i2) } } r.join()"#, "0,4"),
    (r#"function f() { with ({ a: 1 }) { try { throw 1 } catch (e) { return a + e } } } f()"#, "2"),
    (r#"function f(o) { for (;;) { with (o) { if (stop) break; stop = true } } with (o) { return stop } } f({ stop: false })"#, "true"),
    (r#"var p = new Proxy({}, { has(t, k) { return k === 'q' }, get(t, k) { return k === 'q' ? 'trapped' : undefined } }); with (p) { q }"#, "trapped"),
    (r#"var r = []; for (var v of [null, undefined]) { try { with (v) {} } catch (e) { r.push(e.name) } } with (5) { r.push(toFixed(1)) } with ('ab') { r.push(length) } r.join()"#, "TypeError,TypeError,5.0,2"),
    (r#"try { eval('"use strict"; with ({}) {}') } catch (e) { e.name }"#, "SyntaxError"),
    (r#"function f() { 'use strict'; return typeof eval } try { new Function('"use strict"; with (a) {}') } catch (e) { out = e.name }"#, "SyntaxError"),
    (r#"function f(o) { with (o) { eval('var made = secret + 1') } return made } f({ secret: 41 })"#, "42"),
    (r#"function f(o) { with (o) { return (() => inner)() } } f({ inner: 'arrow sees with' })"#, "arrow sees with"),
    // --- private fields
    (r#"class A { #x = 1; getX() { return this.#x } setX(v) { this.#x = v; return this } } var a = new A(); [a.getX(), a.setX(5).getX(), Object.keys(a).length, Reflect.ownKeys(a).length, JSON.stringify(a), Object.getOwnPropertySymbols(a).length].join('|')"#, "1|5|0|0|{}|0"),
    (r#"class A { #x = 1; static peek(o) { return o.#x } } try { A.peek({}) } catch (e) { e.name + ': ' + e.message }"#, "TypeError: Cannot read private member #x from an object whose class did not declare it"),
    (r#"class A { #x = 1; static poke(o) { o.#x = 2 } } try { A.poke({}) } catch (e) { e.name + ': ' + e.message }"#, "TypeError: Cannot write private member #x to an object whose class did not declare it"),
    (r#"class A { #a = 1; inc() { this.#a++; ++this.#a; this.#a += 10; this.#a ??= 5; this.#a ||= 6; this.#a &&= this.#a * 2; return this.#a-- + '|' + this.#a } } new A().inc()"#, "26|25"),
    (r#"class A { #p = 1; #q = this.#p + 1; #u; get sum() { return this.#p + this.#q + '|' + this.#u } } new A().sum"#, "3|undefined"),
    (r#"class A { #x = 1; static t(o) { return o?.#x } } [A.t(new A()), A.t(null), A.t(undefined)].join('|')"#, "1||"),
    (r#"class A { #x = 1; destr() { [this.#x] = [9]; ({ a: this.#x } = { a: this.#x + 1 }); return this.#x } } new A().destr()"#, "10"),
    (r#"class A { #x = 1; eq(o) { return this.#x === o.#x } } class C { #x = 1 } var r = new A().eq(new A()); try { new A().eq(new C()) } catch (e) { r += '|' + e.name } r"#, "true|TypeError"),
    (r#"class B { constructor(o) { return o } } class A extends B { #s = 'stamped'; static read(o) { return o.#s } } var plain = {}; new A(plain); var r = A.read(plain) + '|' + Object.keys(plain).length; try { new A(plain) } catch (e) { r += '|' + e.name } r"#, "stamped|0|TypeError"),
    (r#"class A { #x = 1; static f(o) { o.#x = 2; return o.#x } } var a = Object.freeze(new A()); Object.isFrozen(a) + '|' + A.f(a)"#, "true|2"),
    (r#"class A { #f = () => this; #n = 0; who() { return this.#f() === this } bump = () => ++this.#n } var a = new A(); var b = a.bump; b(); a.who() + '|' + b()"#, "true|2"),
    (r#"class Outer { #o = 'outer'; make() { var self = this; return class Inner { #i = 'inner'; read() { return self.#o + '+' + this.#i } } } } new (new Outer().make())().read()"#, "outer+inner"),
    // --- private methods, accessors, statics, brand checks
    (r#"class A { #m() { return 'm:' + this.#v } #v = 7; get #g() { return this.#v * 2 } set #g(v) { this.#v = v } run() { this.#g = 10; return this.#m() + '|' + this.#g } } new A().run()"#, "m:10|20"),
    (r#"class A { #m() {} same(o) { return this.#m === o.#m } t() { try { this.#m = 1 } catch (e) { return e.name + ': ' + e.message } } } new A().same(new A()) + '|' + new A().t()"#, "true|TypeError: Private method '#m' is not writable"),
    (r#"class A { get #ro() { return 1 } set #wo(v) {} t() { var r = []; try { this.#ro = 2 } catch (e) { r.push(e.message) } try { this.#wo } catch (e) { r.push(e.message) } return r.join('|') } } new A().t()"#, "'#ro' was defined without a setter|'#wo' was defined without a getter"),
    (r#"class A { static #count = 0; static #inc() { return ++A.#count } static make() { A.#inc(); return A.#count } static get #twice() { return A.#count * 2 } static t() { return A.#twice } } A.make() + A.make() + '|' + A.t()"#, "3|4"),
    (r#"class A { static #s = 'S'; static get s() { return A.#s } static viaThis() { return this.#s } } class B extends A {} var r = B.s; try { B.viaThis() } catch (e) { r += '|' + e.name } r"#, "S|TypeError"),
    (r#"class A { #x = 1; #m() {} static has(o) { return #x in o } static hasM(o) { return #m in o } } [A.has(new A()), A.has({}), A.hasM(new A()), A.has(A), A.has(Object.create(new A()))].join()"#, "true,false,true,false,false"),
    (r#"class A { static #brand; static is(o) { return #brand in o } } var r = A.is(A) + '|' + A.is({}); try { A.is(1) } catch (e) { r += '|' + e.name } r"#, "true|false|TypeError"),
    (r#"var out; class A { async #load() { return 'loaded' } *#gen() { yield 1; yield 2 } go() { return this.#load().then(v => { out = v + '|' + [...this.#gen()].join() }) } } new A().go(); 0"#, "loaded|1,2"),
    (r#"var r = []; for (var src of ['class A { foo() { return this.#nope } }', 'var o = { #x: 1 }', 'class A { #x; constructor() { delete this.#x } }', 'class A { #a; #a }', 'this.#x', 'class A { get #g() {} set #g(v) {} #m() {} static #s() {} }', 'class A { #m() {} get #m() {} }', 'class A { get #g() {} get #g() {} }']) { try { eval(src); r.push('ok') } catch (e) { r.push(e.name) } } r.join()"#, "SyntaxError,SyntaxError,SyntaxError,SyntaxError,SyntaxError,ok,SyntaxError,SyntaxError"),
    (r#"var seen = []; var p = new Proxy({ '#x': 'decoy' }, { has(t, k) { seen.push(String(k)); return k in t } }); var got; with (p) { class A { #x = 'real'; #m() { return this.#x } read() { return this.#m() } } got = new A().read() } got + '|' + seen.filter(k => k[0] === '#').length"#, "real|0"),
    // --- static blocks, fields, new.target
    (r#"class A { static x; static y = 2; static { A.x = A.y * 5; this.z = 'z' } } [A.x, A.y, A.z].join()"#, "10,2,z"),
    (r#"var order = []; class A { static a = order.push('a'); static { order.push('block1') } static b = order.push('b'); static { order.push('block2') } } order.join()"#, "a,block1,b,block2"),
    (r#"class A { f = () => this.v; v = 3; ['comp' + 'uted'] = 'c'; 7 = 'seven'; 'quoted key' = 'q' } var a = new A(); var f = a.f; [f(), a.computed, a[7], a['quoted key'], Object.keys(a).join()].join('|')"#, "3|c|seven|q|7,f,v,computed,quoted key"),
    (r#"class Base { constructor() { this.kind = new.target.name } } class Derived extends Base {} function F() { return new.target === undefined ? 'call' : new.target === F ? 'new' : 'other' } [new Base().kind, new Derived().kind, F(), new F() instanceof F, Reflect.construct(F, [], Base) instanceof Base].join()"#, "Base,Derived,call,true,true"),
    (r#"function F() { var arrow = () => new.target; return arrow() === F } [new F() instanceof F, F()].join()"#, "true,false"),
    // --- computed and numeric member names, labelled blocks
    (r#"var k = 'dyn'; var o = { get [k + 1]() { return 'g1' }, set [k + 1](v) { this._s = v }, get 5() { return 'five' }, set 'q r'(v) { this._q = v }, [k]() { return 'm' }, 0x10() { return 16 }, 1.5: 'x' }; o.dyn1 = 'set'; o['q r'] = 'Q'; [o.dyn1, o._s, o[5], o._q, o.dyn(), o[16](), o['1.5']].join('|')"#, "g1|set|five|Q|m|16|x"),
    (r#"var s = Symbol('s'); class A { static [s]() { return 'sym' } get ['a' + 'b']() { return 'ab' } 42() { return 'num' } static 'str key'() { return 'str' } *[Symbol.iterator]() { yield 1 } } var a = new A(); [A[s](), a.ab, a[42](), A['str key'](), [...a].join(), A.prototype[42].name].join('|')"#, "sym|ab|num|str|1|42"),
    (r#"var log = []; a: { log.push(1); b: { log.push(2); break a; } log.push('never'); } c: { if (log.length) break c; log.push('never') } d: e: { break d } log.join()"#, "1,2"),
    (r#"var n = 0; outer: for (var i = 0; i < 3; i++) { inner: { if (i == 1) continue outer; if (i == 2) break inner; n += 10 } n++ } n"#, "12"),
];
